WITH flattened AS (SELECT id, plan, effective_from, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) x AS val), cleaned AS (SELECT *, CONCAT_WS('-', currency, plan) AS currency_plan_key FROM flattened WHERE val < 71), scored AS (SELECT *, DENSE_RANK() OVER (PARTITION BY currency, plan ORDER BY val ASC NULLS LAST) AS val_dense_rank, RANK() OVER (PARTITION BY plan ORDER BY val DESC) AS val_rank, PERCENT_RANK() OVER (ORDER BY val DESC NULLS FIRST) AS val_percent_rank, COUNT(val) OVER w_grp AS currency_count_val, STDDEV_SAMP(val) OVER w_grp AS currency_stddev_samp_val FROM cleaned WINDOW w_grp AS (PARTITION BY currency)), scored_price_tiers AS (SELECT id, plan, effective_from, currency, val, currency_plan_key, val_dense_rank, val_rank, val_percent_rank, currency_count_val, currency_stddev_samp_val, CUME_DIST() OVER (PARTITION BY currency, plan ORDER BY val_percent_rank ASC NULLS FIRST) AS val_percent_rank_cume_dist, PERCENT_RANK() OVER w_recent AS currency_stddev_samp_val_percent_rank, MIN(currency_count_val) OVER w_ordered AS currency_min_currency_count_val FROM scored WINDOW w_recent AS (ORDER BY currency_stddev_samp_val DESC NULLS FIRST), w_ordered AS (PARTITION BY currency)) SELECT *, RANK() OVER (ORDER BY val_percent_rank DESC) AS val_percent_rank_rank, RANK() OVER (ORDER BY val DESC NULLS LAST) AS val_rank_2, CUME_DIST() OVER (ORDER BY currency_stddev_samp_val_percent_rank DESC NULLS FIRST) AS currency_stddev_samp_val_percent_rank_cume_dist, ROUND(val_dense_rank / SUM(val_dense_rank) OVER (PARTITION BY currency), 4) AS val_dense_rank_share, STDDEV_SAMP(val_percent_rank_cume_dist) OVER (PARTITION BY currency) AS currency_stddev_samp_val_percent_rank_cume_dist_2 FROM scored_price_tiers
